fixtures.template:
{% if play_count == 0 %}
    <p>Buy tickets to play.</p>
{% endif %}
<ul>
{% for play in plays %}
    <li>{{ play.ticket_number }}</li>
{% else %}
    <li>No plays yet</li>
{% endfor %}
</ul>
<p>{{ plays|length }} / {{ win_count }}</p>

{% set jackpot = plays|first %}
<h1>{{ jackpot.prize.name|upper }}</h1>
<p>{{ jackpot.prize.value_raw|number_format(2, '.', ',') }} from ticket {{ jackpot.ticket_number }}</p>
<p>{{ win_count }} of {{ play_count }} plays won</p>
{% for play in plays|slice(1, 6) %}
    {% if play.won %}<span class="win">{{ play.prize.name }}{% if play.prize.is_site_credit %} (credit){% endif %}</span>{% else %}<span class="lose">{{ play.ticket_number }}</span>{% endif %}
{% endfor %}
<p>Last ticket: {{ (plays|last).ticket_number }}</p>

{% if win_count == 0 %}
    <p>No luck this time, {{ user.name }}.</p>
{% else %}
    <p>You won!</p>
{% endif %}
{% for play in plays %}
    <p>{{ play.ticket_number }} {{ play.won ? 'won' : 'lost' }} {{ play.prize is null ? 'no prize' : play.prize.name }}</p>
{% endfor %}

{%- set total = 0 -%}
{%- for first in plays -%}
    {%- for second in plays -%}
        {%- for third in plays -%}
            {%- set total = total + 1 -%}
        {%- endfor -%}
    {%- endfor -%}
{%- endfor -%}
<p>{{ total }} iterations over {{ play_count }} plays</p>

{% set greeting = 'Hello' %}
{% set name = user.is_logged_in ? user.display_name : 'guest' %}
{% set numbers = [1, 2, 3, 4] %}
{% set mapping = {'a': 1, 'b': 2} %}
<p>{{ greeting ~ ', ' ~ name }}</p>
{% if play_count > 10 %}
    <p>many</p>
{% elseif play_count > 3 %}
    <p>some</p>
{% else %}
    <p>few</p>
{% endif %}
<p>{{ 3 in numbers ? 'has three' : 'no three' }}</p>
<p>{{ 2 in mapping ? 'value two' : 'no value two' }} {{ mapping.b }}</p>
<p>{{ missing is defined ? 'defined' : 'undefined' }}</p>
<p>{{ plays is empty ? 'empty' : 'not empty' }}</p>
<p>{{ play_count is even ? 'even' : 'odd' }} {{ play_count is odd ? 'odd' : 'even' }}</p>
<p>{{ play_count is divisible by(5) ? 'divisible' : 'not divisible' }}</p>
<p>{{ user.balance_raw is same as(12.5) ? 'same' : 'different' }}</p>
<p>{{ nothing is null ? 'null' : 'set' }} {{ numbers is iterable ? 'iterable' : 'scalar' }}</p>
<p>{{ (play_count * 2 + 1) // 2 }} {{ 7 % 3 }} {{ 2 ** 3 }} {{ 10 / 4 }}</p>
<p>{{ play_count >= 5 and win_count > 0 ? 'both' : 'not both' }} {{ not user.is_logged_in or false ? 'x' : 'y' }}</p>

{% set payload = {'title': 'Tom & "Jerry"', 'tags': ['<b>', "it's"], 'path': '/a/b', 'price': '£5', 'count': play_count, 'flag': true, 'none': null} %}
<script>
    const payload = {{ payload|json }};
    const plays = {{ plays|json }};
    const files = {{ files|json }};
    const settings = {{ settings.primary_color|json }};
    const numbers = {{ [1, 2.5, -3]|json }};
</script>

{% set accent = options.accent_colour|default(settings.primary_color) %}
<section style="--accent: {{ accent }}">
    <h2>{{ options.heading|default('Ending soon') }}</h2>
    {% for competition in competitions.ending_soon|slice(0, options.count|default(3)) %}
        <article>
            <h3>{{ competition.title }}</h3>
            <p>{{ competition.price }} ({{ competition.price_raw|number_format(2) }}), {{ competition.percent_sold }}% sold, {{ competition.tickets_remaining }} left</p>
            <p>{{ competition.category }} {{ competition.is_featured ? 'featured' : '' }} {{ competition.end_date_seconds // 86400 }} days</p>
            {% if options.show_cash_alternative|default(true) %}<p>Cash alternative {{ competition.cash_alt }}</p>{% endif %}
        </article>
    {% endfor %}
    <p>{{ competitions.featured|length }} featured of {{ competitions.all|length }} ({{ products|length }} products)</p>
</section>
